209	// assertScenarioPreviewCoherent re-derives statuses and alert records from
210	// the reported window counts, so one response can never mix a post-batch
211	// count in one window with a pre-batch state elsewhere: a completed trigger
212	// run must carry an alert, a recovery must agree with the alerting status,
213	// and no alert may read recovered while its window still says alerting.
214	func assertScenarioPreviewCoherent(t *testing.T, got scenarioPreview) {
215		t.Helper()
216		const (
217			threshold      = 2
218			triggerWindows = 2
219			recoverWindows = 1
220		)
221		for _, group := range got.Groups {
222			alerting := false
223			triggerRun, recoverRun := 0, 0
224			type wantAlert struct {
225				triggeredAt string
226				recoveredAt *string
227			}
228			var wantAlerts []wantAlert
229			wantStatus := make([]string, len(group.Windows))
230			for i, window := range group.Windows {
231				if !alerting {
232					if window.Count >= threshold {
233						triggerRun++
234						if triggerRun >= triggerWindows {
235							alerting = true
236							triggerRun = 0
237							wantAlerts = append(wantAlerts, wantAlert{triggeredAt: window.Until})
238						}
239					} else {
240						triggerRun = 0
241					}
242				} else if window.Count < threshold {
243					recoverRun++
244					if recoverRun >= recoverWindows {
245						alerting = false
246						recoverRun = 0
247						recovered := window.Until
248						wantAlerts[len(wantAlerts)-1].recoveredAt = &recovered
249					}
250				} else {
251					recoverRun = 0
252				}
253				wantStatus[i] = "normal"
254				if alerting {
255					wantStatus[i] = "alerting"
256				}
257			}
258			for i, window := range group.Windows {
259				if window.Status != wantStatus[i] {
260					t.Fatalf("group %v w%d status=%s does not follow count %d (want %s)",
261						group.LabelValues, i, window.Status, window.Count, wantStatus[i])
262				}
263			}
264			if len(wantAlerts) != len(group.Alerts) {
265				t.Fatalf("group %v has %d alerts but its counts imply %d: %+v vs %+v",
266					group.LabelValues, len(group.Alerts), len(wantAlerts), group.Alerts, wantAlerts)
267			}
268			for i, want := range wantAlerts {
269				alert := group.Alerts[i]
270				if alert.TriggeredAt != want.triggeredAt {
271					t.Fatalf("group %v alert %d triggered_at=%s want %s",
272						group.LabelValues, i, alert.TriggeredAt, want.triggeredAt)
273				}
274				switch {
275				case want.recoveredAt == nil && alert.RecoveredAt != nil:
276					t.Fatalf("group %v alert %d must remain open, recovered at %s",
277						group.LabelValues, i, *alert.RecoveredAt)
278				case want.recoveredAt != nil && (alert.RecoveredAt == nil || *alert.RecoveredAt != *want.recoveredAt):
279					t.Fatalf("group %v alert %d recovered_at=%v want %s",
280						group.LabelValues, i, alert.RecoveredAt, *want.recoveredAt)
281				}
282			}
283		}
284	}
