327	// ensureSlowPreview seeds irrelevant filler events (another service, outside
328	// the scenario range) until one preview round trip takes long enough to
329	// overlap deterministically with a concurrent submission. The fillers never
330	// change the scenario preview.
331	func ensureSlowPreview(t *testing.T, server *httptest.Server) time.Duration {
332		t.Helper()
333		roundTrip := func() time.Duration {
334			start := time.Now()
335			if status, _ := getScenarioPreview(t, server, scenarioPreviewBody); status != http.StatusOK {
336				t.Fatalf("warmup preview: %d", status)
337			}
338			return time.Since(start)
339		}
340		total := 0
341		for round := 0; round < 6; round++ {
342			const chunk = 50000
343			var sb strings.Builder
344			sb.WriteString(`{"events":[`)
345			for i := range chunk {
346				if i > 0 {
347					sb.WriteByte(',')
348				}
349				id := total + i
350				fmt.Fprintf(&sb, `{"id":"filler-%d","service":"filler-svc","severity":"info","message":"m","at":"2026-09-01T00:00:00Z"}`, id)
351			}
352			sb.WriteString(`]}`)
353			if status, out := post(t, server, sb.String()); status != http.StatusOK {
354				t.Fatalf("seed fillers: %d %v", status, out)
355			}
356			total += chunk
357			var slowest time.Duration
358			for range 3 {
359				if d := roundTrip(); d > slowest {
360					slowest = d
361				}
362			}
363			if slowest >= 20*time.Millisecond {
364				return slowest
365			}
366		}
367		return roundTrip()
368	}
