375	// TestPreviewOverlappingBatchCommitHTTP overlaps real preview requests with
376	// a batch held mid commit:
377	//
378	//   - A preview already scanning when the submission reaches the timeline
379	//     lock must finish with the complete pre-submission state.
380	//   - Every preview whose read lock is queued while the durable commit is
381	//     pending must return with the complete post-submission state.
382	//
383	// Either way a single response may count only the full batch or none of it:
384	// no partial counts, no mix of groups across states, and no statuses/alerts
385	// that its own counts do not imply.
386	func TestPreviewOverlappingBatchCommitHTTP(t *testing.T) {
387		server, store, _ := newTestServer(t)
388		if status, out := post(t, server, scenarioOldSeed); status != http.StatusOK {
389			t.Fatalf("seed: %d %v", status, out)
390		}
391		status, before := getScenarioPreview(t, server, scenarioPreviewBody)
392		if status != http.StatusOK {
393			t.Fatalf("preview before: %d", status)
394		}
395		scanTime := ensureSlowPreview(t, server)
396	
397		earlyCh := make(chan previewCall, 1)
398		go func() {
399			st, body := getScenarioPreview(t, server, scenarioPreviewBody)
400			earlyCh <- previewCall{st, body}
401		}()
402		// Start the submission while the slow preview is (almost certainly)
403		// mid-scan; the assertions below are correct for either scheduling
404		// outcome.
405		time.Sleep(scanTime / 2)
406	
407		release, entered := store.armStall()
408		postCh := make(chan map[string]any, 1)
409		postStatus := make(chan int, 1)
410		go func() {
411			st, out := post(t, server, scenarioBatch)
412			postStatus <- st
413			postCh <- out
414		}()
415		<-entered
416	
417		// The commit hook is now holding the timeline write lock. Previews
418		// launched here queue behind it and, by RWMutex writer preference, scan
419		// only after the batch commits, so they deterministically pin the
420		// post-submission side of the overlap.
421		const readers = 8
422		var wg sync.WaitGroup
423		calls := make([]previewCall, readers)
424		for i := range readers {
425			wg.Add(1)
426			go func(i int) {
427				defer wg.Done()
428				st, body := getScenarioPreview(t, server, scenarioPreviewBody)
429				calls[i] = previewCall{st, body}
430			}(i)
431		}
432		time.Sleep(30 * time.Millisecond)
433		close(release)
434	
435		if st := <-postStatus; st != http.StatusOK {
436			t.Fatalf("batch submit status=%d body=%v", st, <-postCh)
437		}
438		if out := <-postCh; out["created"].(float64) != 5 {
439			t.Fatalf("batch counts after release: %v", out)
440		}
441		wg.Wait()
442	
443		status, after := getScenarioPreview(t, server, scenarioPreviewBody)
444		if status != http.StatusOK {
445			t.Fatalf("preview after: %d", status)
446		}
447		assertScenarioPreviewAfter(t, after)
448		assertScenarioPreviewCoherent(t, after)
449		if reflect.DeepEqual(before, after) {
450			t.Fatal("pre- and post-batch previews must differ")
451		}
452		for i, call := range calls {
453			if call.status != http.StatusOK {
454				t.Fatalf("queued preview %d status=%d", i, call.status)
455			}
456			assertScenarioPreviewCoherent(t, call.body)
457			if !reflect.DeepEqual(call.body, after) {
458				t.Fatalf("queued preview %d must show the complete post-batch state:\n%+v\n%+v",
459					i, call.body, after)
460			}
461		}
462	
463		// The preview in flight when the submission started must be one whole
464		// state or the other, never a splice: it scanned either before the
465		// writer's commit (pre) or after the lock passed to queued readers (post).
466		early := <-earlyCh
467		if early.status != http.StatusOK {
468			t.Fatalf("overlapping preview status=%d", early.status)
469		}
470		assertScenarioPreviewCoherent(t, early.body)
471		pre := reflect.DeepEqual(early.body, before)
472		post := reflect.DeepEqual(early.body, after)
473		if !pre && !post {
474			t.Fatalf("overlapping preview must be the complete pre- or post-batch state, got a splice:\n%+v", early.body)
475		}
476	}
477	
478	func TestPreviewUnchangedAfterConflictBatchesHTTP(t *testing.T) {
479		server, _, _ := newTestServer(t)
480		if status, out := post(t, server, scenarioOldSeed); status != http.StatusOK {
481			t.Fatalf("seed: %d %v", status, out)
482		}
483		status, before := getScenarioPreview(t, server, scenarioPreviewBody)
484		if status != http.StatusOK {
485			t.Fatalf("preview before: %d", status)
486		}
487		assertScenarioPreviewBefore(t, before)
488	
489		// One event clashes with stored content: the whole batch is rejected 409
490		// and none of its other events may move the preview.
491		if status, out := post(t, server, scenarioConflictBatch); status != http.StatusConflict {
492			t.Fatalf("conflict batch must be 409, got %d %v", status, out)
493		}
494		status, afterConflict := getScenarioPreview(t, server, scenarioPreviewBody)
495		if status != http.StatusOK {
496			t.Fatalf("preview after conflict: %d", status)
497		}
498		if !reflect.DeepEqual(afterConflict, before) {
499			t.Fatalf("409 batch must leave the preview untouched:\n%+v\n%+v", afterConflict, before)
500		}
501	
502		// A repeated id inside the batch is rejected just as wholesale.
503		if status, out := post(t, server, scenarioDuplicateBatch); status != http.StatusConflict {
504			t.Fatalf("duplicate-id batch must be 409, got %d %v", status, out)
505		}
506		_, afterDuplicate := getScenarioPreview(t, server, scenarioPreviewBody)
507		if !reflect.DeepEqual(afterDuplicate, before) {
508			t.Fatalf("duplicate-id batch must leave the preview untouched:\n%+v", afterDuplicate)
509		}
510	
511		// The rejected submissions created no incidents and changed no events:
512		// the stored timeline still holds exactly the three seeded events.
513		if status, got := get(t, server, "?service=svc"); status != http.StatusOK {
514			t.Fatalf("list events: %d", status)
515		} else if len(got.([]any)) != 3 {
516			t.Fatalf("rejected batches must store nothing, timeline has %v events", got)
517		}
518	
519		// A clean submission still moves the preview to the full post state.
520		if status, out := post(t, server, scenarioBatch); status != http.StatusOK {
521			t.Fatalf("valid batch: %d %v", status, out)
522		} else if out["created"].(float64) != 5 {
523			t.Fatalf("valid batch counts: %v", out)
524		}
525		status, after := getScenarioPreview(t, server, scenarioPreviewBody)
526		if status != http.StatusOK {
527			t.Fatalf("preview after valid batch: %d", status)
528		}
529		assertScenarioPreviewAfter(t, after)
530	}
