26	func scenarioAnchor() time.Time {
27		return time.Date(2026, 10, 1, 10, 0, 0, 0, time.UTC)
28	}
29	
30	func scenarioQuery() AlertPreviewQuery {
31		t0 := scenarioAnchor()
32		return AlertPreviewQuery{
33			Service:        "svc",
34			Since:          t0,
35			Until:          t0.Add(3 * time.Minute),
36			Window:         time.Minute,
37			Threshold:      2,
38			TriggerWindows: 2,
39			RecoverWindows: 1,
40			GroupLabels:    []string{"grp"},
41		}
42	}
43	
44	// seedScenarioOldData commits only the old group: two events in window 0,
45	// one in window 1, window 2 empty.
46	func seedScenarioOldData(t *testing.T, tl *Timeline) {
47		t.Helper()
48		t0 := scenarioAnchor()
49		old := []Event{
50			scenarioEvent("o0a", "old", t0.Add(5*time.Second)),
51			scenarioEvent("o0b", "old", t0.Add(30*time.Second)),
52			scenarioEvent("o10", "old", t0.Add(65*time.Second)),
53		}
54		if _, err := tl.Ingest(old, nil); err != nil {
55			t.Fatalf("seed: %v", err)
56		}
57	}
58	
59	// scenarioBatch tops the old group's middle window up and fills the new
60	// group's first two windows, all in one submission.
61	func scenarioBatch() []Event {
62		t0 := scenarioAnchor()
63		return []Event{
64			scenarioEvent("o11", "old", t0.Add(100*time.Second)),
65			scenarioEvent("n0a", "new", t0.Add(10*time.Second)),
66			scenarioEvent("n0b", "new", t0.Add(20*time.Second)),
67			scenarioEvent("n10", "new", t0.Add(70*time.Second)),
68			scenarioEvent("n11", "new", t0.Add(110*time.Second)),
69		}
70	}
71	
72	func scenarioEvent(id, group string, at time.Time) Event {
73		return Event{
74			ID:       id,
75			Service:  "svc",
76			Severity: "info",
77			Message:  "m",
78			At:       at,
79			Labels:   map[string]string{"grp": group},
80		}
81	}
82	
83	func findScenarioGroup(t *testing.T, result AlertPreviewResult, value string) *AlertGroup {
84		t.Helper()
85		for i := range result.Groups {
86			g := &result.Groups[i]
87			if len(g.LabelValues) == 1 && g.LabelValues[0] != nil && *g.LabelValues[0] == value {
88				return g
89			}
90		}
91		t.Fatalf("group grp=%q not found in %+v", value, result.Groups)
92		return nil
93	}
94	
95	// assertScenarioBefore pins the pre-submission observation: only the old
96	// group exists, its counts never reach two consecutive threshold hits, the
97	// empty window is retained, and no alert exists.
98	func assertScenarioBefore(t *testing.T, result AlertPreviewResult) {
99		t.Helper()
100		if !reflect.DeepEqual(result.GroupLabelNames, []string{"grp"}) {
101			t.Fatalf("group label names: %v", result.GroupLabelNames)
102		}
103		if len(result.Groups) != 1 {
104			t.Fatalf("before the batch only the old group exists, got %d groups", len(result.Groups))
105		}
106		old := findScenarioGroup(t, result, "old")
107		assertWindowCounts(t, old, []int{2, 1, 0})
108		for i, window := range old.Windows {
109			if window.Status != AlertStatusNormal {
110				t.Fatalf("old group must never alert before the batch, w%d=%s", i, window.Status)
111			}
112		}
113		if len(old.Alerts) != 0 {
114			t.Fatalf("old group must have no alerts before the batch, got %+v", old.Alerts)
115		}
116	}
117	
118	// assertScenarioAfter pins the post-submission observation: both groups
119	// carry [2,2,0], alert at the end of window 1 and recover at the end of the
120	// empty window 2.
121	func assertScenarioAfter(t *testing.T, result AlertPreviewResult) {
122		t.Helper()
123		if len(result.Groups) != 2 {
124			t.Fatalf("after the batch both groups exist, got %d groups", len(result.Groups))
125		}
126		t0 := scenarioAnchor()
127		for _, value := range []string{"old", "new"} {
128			group := findScenarioGroup(t, result, value)
129			assertWindowCounts(t, group, []int{2, 2, 0})
130			wantStatus := []string{AlertStatusNormal, AlertStatusAlerting, AlertStatusNormal}
131			for i, window := range group.Windows {
132				if window.Status != wantStatus[i] {
133					t.Fatalf("group %s w%d status=%s want %s", value, i, window.Status, wantStatus[i])
134				}
135			}
136			if len(group.Alerts) != 1 {
137				t.Fatalf("group %s must have one alert cycle, got %+v", value, group.Alerts)
138			}
139			alert := group.Alerts[0]
140			if !alert.OpenedAt.Equal(t0.Add(2 * time.Minute)) {
141				t.Fatalf("group %s triggers at end of window 1, got %s", value, alert.OpenedAt)
142			}
143			if alert.RecoveredAt == nil || !alert.RecoveredAt.Equal(t0.Add(3*time.Minute)) {
144				t.Fatalf("group %s recovers at end of the empty window 2, got %v", value, alert.RecoveredAt)
145			}
146		}
147	}
148	
149	func assertWindowCounts(t *testing.T, group *AlertGroup, want []int) {
150		t.Helper()
151		if len(group.Windows) != len(want) {
152			t.Fatalf("group %v: got %d windows, want %d", group.LabelValues, len(group.Windows), len(want))
153		}
154		for i, window := range group.Windows {
155			if window.Count != want[i] {
156				t.Fatalf("group %v w%d count=%d, want %d", group.LabelValues, i, window.Count, want[i])
157			}
158		}
159	}
160	
161	// assertPreviewCoherent re-derives every end-of-window status and every
162	// alert trigger/recovery record from the reported counts, so a response can
163	// never pass with threshold runs lacking an alert or with an alert that
164	// recovered while a window still reports alerting.
165	func assertPreviewCoherent(t *testing.T, query AlertPreviewQuery, result AlertPreviewResult) {
166		t.Helper()
167		for _, group := range result.Groups {
168			alerting := false
169			triggerRun, recoverRun := 0, 0
170			var wantAlerts []AlertRecord
171			wantStatus := make([]string, len(group.Windows))
172			for i, window := range group.Windows {
173				if !alerting {
174					if window.Count >= query.Threshold {
175						triggerRun++
176						if triggerRun >= query.TriggerWindows {
177							alerting = true
178							triggerRun = 0
179							wantAlerts = append(wantAlerts, AlertRecord{OpenedAt: window.End})
180						}
181					} else {
182						triggerRun = 0
183					}
184				} else {
185					if window.Count < query.Threshold {
186						recoverRun++
187						if recoverRun >= query.RecoverWindows {
188							alerting = false
189							recoverRun = 0
190							end := window.End
191							wantAlerts[len(wantAlerts)-1].RecoveredAt = &end
192						}
193					} else {
194						recoverRun = 0
195					}
196				}
197				wantStatus[i] = AlertStatusNormal
198				if alerting {
199					wantStatus[i] = AlertStatusAlerting
200				}
201			}
202			for i, window := range group.Windows {
203				if window.Status != wantStatus[i] {
204					t.Fatalf("group %v w%d status %s does not follow its counts: want %s (count=%d)",
205						group.LabelValues, i, window.Status, wantStatus[i], window.Count)
206				}
207			}
208			if len(wantAlerts) != len(group.Alerts) {
209				t.Fatalf("group %v has %d alerts but its counts imply %d: %+v vs %+v",
210					group.LabelValues, len(group.Alerts), len(wantAlerts), group.Alerts, wantAlerts)
211			}
212			for i := range wantAlerts {
213				got, want := group.Alerts[i], wantAlerts[i]
214				if !got.OpenedAt.Equal(want.OpenedAt) {
215					t.Fatalf("group %v alert %d triggered_at=%s want %s",
216						group.LabelValues, i, got.OpenedAt, want.OpenedAt)
217				}
218				switch {
219				case want.RecoveredAt == nil && got.RecoveredAt != nil:
220					t.Fatalf("group %v alert %d must stay open, recovered at %s",
221						group.LabelValues, i, *got.RecoveredAt)
222				case want.RecoveredAt != nil && (got.RecoveredAt == nil || !got.RecoveredAt.Equal(*want.RecoveredAt)):
223					t.Fatalf("group %v alert %d recovered_at=%v want %s",
224						group.LabelValues, i, got.RecoveredAt, *want.RecoveredAt)
225				}
226			}
227		}
228	}
