230	func TestPreviewScenarioBeforeAndAfterWholeBatch(t *testing.T) {
231		tl := NewTimeline()
232		query := scenarioQuery()
233		seedScenarioOldData(t, tl)
234	
235		before, err := tl.PreviewAlerts(query)
236		if err != nil {
237			t.Fatalf("preview before: %v", err)
238		}
239		assertScenarioBefore(t, before)
240		assertPreviewCoherent(t, query, before)
241	
242		result, err := tl.Ingest(scenarioBatch(), nil)
243		if err != nil {
244			t.Fatalf("ingest: %v", err)
245		}
246		if result.Created != 5 || result.Replayed != 0 {
247			t.Fatalf("batch result = %+v, want created=5", result)
248		}
249	
250		// A preview issued once the successful ingestion has returned must show
251		// the complete post-submission observation, never a partial count.
252		after, err := tl.PreviewAlerts(query)
253		if err != nil {
254			t.Fatalf("preview after: %v", err)
255		}
256		assertScenarioAfter(t, after)
257		assertPreviewCoherent(t, query, after)
258	}
259	
260	// ensureSlowScan grows the timeline with irrelevant events until one preview
261	// scan takes long enough to overlap deterministically with another caller.
262	// The filler events belong to another service and fall outside the scenario
263	// range, so they never change a preview result; they only widen the scan.
264	func ensureSlowScan(t *testing.T, tl *Timeline, query AlertPreviewQuery) time.Duration {
265		t.Helper()
266		base := scenarioAnchor().AddDate(0, -1, 0)
267		scan := func() time.Duration {
268			start := time.Now()
269			if _, err := tl.PreviewAlerts(query); err != nil {
270				t.Fatalf("warmup preview: %v", err)
271			}
272			return time.Since(start)
273		}
274		total := 0
275		for round := 0; round < 6; round++ {
276			const chunk = 100000
277			fillers := make([]Event, 0, chunk)
278			for i := range chunk {
279				fillers = append(fillers, Event{
280					ID:       "filler-" + strconv.Itoa(total+i),
281					Service:  "filler-svc",
282					Severity: "info",
283					Message:  "m",
284					At:       base.Add(time.Duration(total+i) * time.Nanosecond),
285				})
286			}
287			if _, err := tl.Ingest(fillers, nil); err != nil {
288				t.Fatalf("seed fillers: %v", err)
289			}
290			total += chunk
291			var slowest time.Duration
292			for range 3 {
293				if d := scan(); d > slowest {
294					slowest = d
295				}
296			}
297			if slowest >= 5*time.Millisecond {
298				return slowest
299			}
300		}
301		return scan()
302	}
303	
304	// TestPreviewOverlappingBatchCommitIsOneSnapshot overlaps previews with a
305	// whole-batch submission:
306	//
307	//   - A preview already scanning when the submission reaches the timeline
308	//     lock finishes with the complete pre-submission state.
309	//   - Every preview whose read lock is queued while the commit hook is held
310	//     runs after the commit and returns the complete post-submission state.
311	//
312	// A single response may therefore contain the full batch or none of it; the
313	// test also asserts the general contract on the in-flight preview: whichever
314	// side scheduling chose, the result must be one whole observation, never a
315	// splice with a partial batch, mixed group snapshots, or statuses/alerts that
316	// the reported counts do not imply.
317	func TestPreviewOverlappingBatchCommitIsOneSnapshot(t *testing.T) {
318		tl := NewTimeline()
319		query := scenarioQuery()
320		seedScenarioOldData(t, tl)
321	
322		before, err := tl.PreviewAlerts(query)
323		if err != nil {
324			t.Fatalf("preview before: %v", err)
325		}
326		scanTime := ensureSlowScan(t, tl, query)
327	
328		earlyDone := make(chan AlertPreviewResult, 1)
329		go func() {
330			result, err := tl.PreviewAlerts(query)
331			if err != nil {
332				t.Errorf("early preview: %v", err)
333				return
334			}
335			earlyDone <- result
336		}()
337		// Start the submission while the slow preview is (almost certainly)
338		// mid-scan; the assertions below hold for either scheduling outcome.
339		time.Sleep(scanTime / 2)
340	
341		entered := make(chan struct{})
342		release := make(chan struct{})
343		ingestDone := make(chan struct{})
344		go func() {
345			defer close(ingestDone)
346			result, err := tl.Ingest(scenarioBatch(), func(persisted []Event) error {
347				close(entered)
348				<-release
349				return nil
350			})
351			if err != nil {
352				t.Errorf("blocked ingest: %v", err)
353				return
354			}
355			if result.Created != 5 {
356				t.Errorf("batch created=%d, want 5", result.Created)
357			}
358		}()
359		<-entered
360	
361		// The commit hook holds the write lock now; these previews queue behind
362		// it and scan only after the batch commits.
363		const readers = 24
364		observed := make(chan AlertPreviewResult, readers)
365		var wg sync.WaitGroup
366		for range readers {
367			wg.Add(1)
368			go func() {
369				defer wg.Done()
370				result, err := tl.PreviewAlerts(query)
371				if err != nil {
372					t.Errorf("queued preview: %v", err)
373					return
374				}
375				observed <- result
376			}()
377		}
378		// Give the previews time to pile onto the pending write lock; the
379		// guarantee does not depend on this delay, it only widens coverage.
380		time.Sleep(20 * time.Millisecond)
381		close(release)
382		<-ingestDone
383		wg.Wait()
384		close(observed)
385	
386		after, err := tl.PreviewAlerts(query)
387		if err != nil {
388			t.Fatalf("preview after: %v", err)
389		}
390		assertScenarioAfter(t, after)
391		assertPreviewCoherent(t, query, after)
392		if reflect.DeepEqual(before, after) {
393			t.Fatal("pre- and post-batch observations must differ")
394		}
395	
396		count := 0
397		for result := range observed {
398			count++
399			assertPreviewCoherent(t, query, result)
400			if !reflect.DeepEqual(result, after) {
401				t.Fatalf("queued preview must show the whole post-batch state:\n%+v", summarizePreview(result))
402			}
403		}
404		if count != readers {
405			t.Fatalf("collected %d queued previews, want %d", count, readers)
406		}
407	
408		// The preview in flight when the submission started must be exactly one
409		// committed observation: fully pre-batch or fully post-batch.
410		early := <-earlyDone
411		assertPreviewCoherent(t, query, early)
412		pre := reflect.DeepEqual(early, before)
413		post := reflect.DeepEqual(early, after)
414		if !pre && !post {
415			t.Fatalf("overlapping preview must be the complete pre- or post-batch state, got a splice:\n%+v",
416				summarizePreview(early))
417		}
418	}
419	
420	// TestPreviewUnchangedAfterConflictBatch covers the 409 contract: when one
421	// event conflicts with stored content (or an id repeats inside the batch),
422	// none of the batch's other events may become visible and the preview stays
423	// identical to the observation taken before the rejected submission.
424	func TestPreviewUnchangedAfterConflictBatch(t *testing.T) {
425		tl := NewTimeline()
426		query := scenarioQuery()
427		seedScenarioOldData(t, tl)
428	
429		before, err := tl.PreviewAlerts(query)
430		if err != nil {
431			t.Fatalf("preview before: %v", err)
432		}
433	
434		// A batch whose valid events would create the new group and top up the
435		// old one, but whose last event reuses a stored id with new content.
436		conflict := append(scenarioBatch(), Event{
437			ID:       "o10",
438			Service:  "svc",
439			Severity: "info",
440			Message:  "changed content",
441			At:       scenarioAnchor().Add(65 * time.Second),
442			Labels:   map[string]string{"grp": "old"},
443		})
444		if _, err := tl.Ingest(conflict, nil); !IsConflictError(err) {
445			t.Fatalf("changed content for a stored id must conflict, got %v", err)
446		}
447		after, err := tl.PreviewAlerts(query)
448		if err != nil {
449			t.Fatalf("preview after conflict: %v", err)
450		}
451		if !reflect.DeepEqual(before, after) {
452			t.Fatalf("409 batch changed the preview:\nbefore=%+v\nafter =%+v", summarizePreview(before), summarizePreview(after))
453		}
454		if got := tl.Query(Query{}); len(got) != 3 {
455			t.Fatalf("rejected batch must store nothing, timeline has %d events", len(got))
456		}
457	
458		// An id repeated inside the batch is rejected wholesale as well.
459		batch := scenarioBatch()
460		dup := append(append([]Event{}, batch...), batch[0])
461		if _, err := tl.Ingest(dup, nil); !IsConflictError(err) {
462			t.Fatalf("repeated id within batch must conflict, got %v", err)
463		}
464		again, err := tl.PreviewAlerts(query)
465		if err != nil {
466			t.Fatalf("preview after duplicate batch: %v", err)
467		}
468		if !reflect.DeepEqual(before, again) {
469			t.Fatalf("duplicate-id batch changed the preview: %+v", summarizePreview(again))
470		}
471	
472		// The untouched dataset still moves to the full post state once a valid
473		// batch commits, proving the equality checks above were discriminating.
474		if _, err := tl.Ingest(scenarioBatch(), nil); err != nil {
475			t.Fatalf("valid batch after conflicts: %v", err)
476		}
477		committed, err := tl.PreviewAlerts(query)
478		if err != nil {
479			t.Fatalf("preview after valid batch: %v", err)
480		}
481		assertScenarioAfter(t, committed)
482	}
483	
484	func summarizePreview(result AlertPreviewResult) []struct {
485		group  string
486		counts []int
487		alerts []AlertRecord
488	} {
489		summary := make([]struct {
490			group  string
491			counts []int
492			alerts []AlertRecord
493		}, 0, len(result.Groups))
494		for _, group := range result.Groups {
495			name := ""
496			if len(group.LabelValues) == 1 && group.LabelValues[0] != nil {
497				name = *group.LabelValues[0]
498			}
499			counts := make([]int, len(group.Windows))
500			for i, window := range group.Windows {
501				counts[i] = window.Count
502			}
503			summary = append(summary, struct {
504				group  string
505				counts []int
506				alerts []AlertRecord
507			}{name, counts, group.Alerts})
508		}
509		return summary
510	}
