// summarizeAggregate renders counts/deltas per series so a splice failure
// shows every series and segment, not just the first mismatch.
func summarizeAggregate(got []AggregateSeries) string {
	out := ""
	for _, s := range got {
		out += "a=" + s.Labels["a"] + "{"
		for i, seg := range s.Segments {
			if i > 0 {
				out += " "
			}
			out += "c=" + itoa(seg.Count) + ",d=" + ftoa(seg.Delta)
		}
		out += "} "
	}
	return out
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b [24]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func ftoa(f float64) string {
	return formatFloat(f)
}

