package metrics

import (
	"testing"
	"time"
)

func TestProbeSlowAggregate(t *testing.T) {
	s := NewStore()
	query := aggScenarioQuery()
	if _, err := s.Ingest(scenarioSeedSamples(), nil); err != nil {
		t.Fatal(err)
	}
	base := aggScenarioAnchor().AddDate(0, -1, 0)
	total := 0
	for round := 0; round < 6; round++ {
		const chunk = 40000
		fillers := make([]Sample, 0, chunk)
		for i := range chunk {
			id := "filler-" + itoaProbe(total+i)
			fillers = append(fillers, Sample{
				ID: id, Service: "filler-svc", Name: "requests",
				At:    base.Add(time.Duration(total+i) * time.Nanosecond),
				Value: float64(total + i),
				Labels: map[string]string{"i": id},
			})
		}
		start := time.Now()
		if _, err := s.Ingest(fillers, noopCommit); err != nil {
			t.Fatal(err)
		}
		ingestD := time.Since(start)
		total += chunk
		var slowest time.Duration
		for range 3 {
			st := time.Now()
			if _, err := s.Aggregate(query); err != nil {
				t.Fatal(err)
			}
			if d := time.Since(st); d > slowest {
				slowest = d
			}
		}
		t.Logf("round=%d totalSeries=%d ingest=%v aggregateSlowest=%v", round, total, ingestD, slowest)
	}
}

func itoaProbe(n int) string {
	return strconvProbe(n)
}

