		// the metric store lock, so no other Append can reach here at once.
		close(entered)
		<-stall
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failNext {
		f.poisoned = true
		f.failNext = false
		return errors.New("simulated metric write failure")
	}
	f.batches = append(f.batches, append([]metrics.Sample(nil), batch...))
	return nil
}

